INSERT INTO `wp_addonlibrary_addons` (`id`, `title`, `name`, `alias`, `addontype`, `description`, `ordering`, `templates`, `config`, `catid`, `is_active`, `test_slot1`, `test_slot2`, `test_slot3`) VALUES
(1, 'WooCommerce Product List', 'woocommerce_product_list_elementor', 'woocommerce_product_list', 'elementor', 'Showcase your WooCommerce products in an attractive list layout with many customization options. You can choose how many products to show per page, what information to display about each product, and much more.', 1, '{\"html\":\"<div id=\\\"{{uc_id}}\\\"  class=\\\"product-list-cont{{uc_filtering_addclass}}{{remote_parent.class}} {{uc_dynamic_popup_class}}\\\" {{uc_filtering_attributes|raw}} {{remote_parent.attributes|raw}} >\\n\\t<ul class=\\\"product-list uc-items-wrapper\\\">\\n\\n\\t\\t{{put_items()}}\\n\\n\\n\\t<\\/ul>\\n<\\/div>\\n\\n\\n{% if show_empty_message == \\\"true\\\" %}\\n\\n  <div id=\\\"{{uc_id}}_empty_message\\\" class=\\\"ue-no-posts-found\\\" {% if uc_num_items > 0 %} style=\\\"display:none\\\" {% endif %}>{{no_posts_found|raw}}<\\/div>\\n\\n{% endif %}\",\"html_item\":\"<li class=\\\"product-items\\\" style=\\\"overflow:hidden;\\\" id=\\\"{{item.item_id}}\\\"> \\n\\n  \\t{% if(enable_third_party_integrations == \\\"true\\\")%}\\n    \\t{{do_action(\'ue_woocommerce_product_integrations\', item.product.id)}}\\n\\t{%endif%}\\n  \\n            {% if show_image == \\\"true\\\" %}\\n             \\t<div class=\\\"product-img\\\" href=\\\"{{item.product.link}}\\\">\\n                  \\n                  \\n                  {% if item.product.image is empty %}\\n                      <img src=\\\"{{empty_image_placeholder}}\\\" {{empty_image_placeholder_attributes|raw}}>\\n                  {% else %} \\n                      <img src=\\\"{{item.product.image}}\\\" {{item.product.image_attributes|raw}}>\\n                  {% endif %}\\t\\n                  \\n                   \\n                 \\n                   {% if badge == \\\"image\\\" %}\\n                   \\t{% if show_labels == \\\"true\\\" %}\\n                      {% if(item.product.woo_stock_status == \\\"outofstock\\\") %}\\n                        <div class=\\\"ue_woocommerce_product_label ue_woocommerce_product_grid_out_of_stock_label\\\">{{out_of_stock_text|raw}}<\\/div>\\n                      {% else %}\\n                        {% if item.product.woo_sale_price is empty %}\\n                        {% else %}\\n                           <div class=\\\"ue_woocommerce_product_label ue_woocommerce_product_list_badge\\\">\\n                             {{sale_label|raw}} \\n                             {% if show_sale_precent_in_label == \\\"true\\\" %}\\n                               {{item.product.woo_discount_percent}}%\\n                             {% endif %}\\n                             {{sale_label_end_text|raw}}\\n                           <\\/div>\\n                        {% endif %}\\n                      {% endif %}\\n                    {% endif %}\\n                   {% endif %} \\n                  \\n                  <div class=\\\"product-img-overlay\\\">\\n                    <div class=\\\"uc-buttons\\\">\\n                      {% if (show_product_button == \\\"true\\\") and (product_button_type == \\\"image_overlay\\\") %}\\n                      \\n                      \\t<a href=\\\"{{item.product.link}}\\\" {{item.product.dynamic_popup_link_attributes|raw}} class=\\\"product-text-btn {{item.product.dynamic_popup_link_class}}\\\" > {{product_page_button_text|raw}}<\\/a> \\n                      \\n                      {% endif %}\\n                      \\n                      {% if cart_button == \\\"image_overlay\\\" %} \\n                  \\n                      {% if(item.product.woo_type == \\\"variable\\\") %}\\n                          {% set buttonAddCartTextCombined = select_options_button_text %}        \\t\\n                      {% else %}\\n                          {% set buttonAddCartTextCombined = cart_button_text %}\\n                      {% endif %}\\n                                    \\n                          <a {{item.product.woo_addcart_ajax_attributes|raw}}>{{ buttonAddCartTextCombined|raw}}<\\/a>                  \\n                                    \\t\\n                  {% endif %}\\n                    <\\/div>   \\n                  <\\/div>\\n                <\\/div> \\n  \\n  \\t\\t\\t\\t <div class=\\\"uc-product-items-spacer\\\"><\\/div>\\n            {% endif %}\\t\\n\\t\\t\\t\\n           \\n\\n\\t\\t\\t<div class=\\\"product-text\\\"> \\n              \\n              {% if badge == \\\"content\\\" %}\\n               {% if show_labels == \\\"true\\\" %}\\n              \\t{% if(item.product.woo_stock_status == \\\"outofstock\\\") %}\\n                  <div class=\\\"ue_woocommerce_product_label ue_woocommerce_product_grid_out_of_stock_label\\\">{{out_of_stock_text|raw}}<\\/div>\\n                {% else %}\\n                  {% if item.product.woo_sale_price is empty %}\\n                  {% else %}\\n                     <div class=\\\"ue_woocommerce_product_label ue_woocommerce_product_list_badge\\\">\\n                       {{sale_label|raw}} \\n                       {% if show_sale_precent_in_label == \\\"true\\\" %}\\n                         {{item.product.woo_discount_percent}}%\\n                       {% endif %}\\n                       {{sale_label_end_text|raw}}\\n                     <\\/div>\\n                  {% endif %}\\n              \\t{% endif %}\\n               {% endif %}\\t\\n              {% endif %}\\n              \\n              {% if category == \\\"above\\\" %}\\n\\t\\t\\t\\t<div class=\\\"ue-product-category\\\"><a  href=\\\"{{item.product.category_link}}\\\">{{item.product.category_name}} <\\/a><\\/div>\\n              {% endif %}\\n              \\n              {% if show_title == \\\"true\\\" %}\\n\\t\\t\\t\\t<a class=\\\"product-text-name\\\" href=\\\"{{item.product.link}}\\\">{{item.product.title|raw}} <\\/a>\\n              {% endif %}\\t\\n              \\n              {% if category == \\\"under\\\" %}\\n\\t\\t\\t\\t<div class=\\\"ue-product-category\\\"><a class=\\\"ue-product-category\\\" href=\\\"{{item.product.category_link}}\\\">{{item.product.category_name}} <\\/a><\\/div>\\n              {% endif %}\\n              \\n              {% if show_description == \\\"short\\\" %}\\n              <div class=\\\"product-short-description\\\">{{item.product.intro|raw}}<\\/div>\\n              {% endif %}\\n              \\n              {% if show_description == \\\"full\\\" %}\\n              <div class=\\\"product-short-description\\\">{{item.product.intro_full|truncate(10000)}}<\\/div>\\n              {% endif %}\\n              \\n              {% if show_rating == \\\"true\\\" %}\\n              <div class=\\\"product-rating\\\">\\n                {%for staritem in item.product.woo_rating_stars %}                \\n                    <i class=\\\"{{staritem.class}}\\\"><\\/i>\\n                {% endfor %}\\n              <\\/div>\\n              {% endif %}\\n              \\n              <div class=\\\"product-text-wrapper uc-prices\\\">\\n         \\n                {% if show_regular_price == \\\"true\\\" and item.product.woo_sale_price is not empty %}  \\n\\t\\t\\t\\t\\t\\n                      {%if item.product.woo_type == \\\"variable\\\" %}\\n\\n                            {% if item.product.woo_regular_price_from == item.product.woo_regular_price_to %}\\n                                <span class=\\\"product-text-price uc_regular_price\\\">{{item.product.woo_regular_price|wc_price|raw}}<\\/span> <span class=\\\"uc_price_spacer\\\" style=\\\"display:inline-block;\\\"><\\/span> \\n                            {% else %}\\n                                <span class=\\\"product-text-price uc_regular_price\\\">{{item.product.woo_regular_price_from|wc_price(item.product.woo_regular_price_from_id)|raw}}<\\/span> - <span class=\\\"product-text-price uc_regular_price\\\">{{item.product.woo_regular_price_to|wc_price(item.product.woo_regular_price_to_id)|raw}}<\\/span><span class=\\\"uc_price_spacer\\\" style=\\\"display:inline-block;\\\"><\\/span> \\n                            {% endif %}\\n                      {%else%}\\n                            <span class=\\\"product-text-price uc_regular_price\\\">{{item.product.woo_regular_price|wc_price|raw}}<\\/span> <span class=\\\"uc_price_spacer\\\" style=\\\"display:inline-block;\\\"><\\/span> \\n                       {%endif%}\\n                    {% endif %}\\n                    \\n                 {% if show_sale_price == \\\"true\\\" %}\\n\\t\\t\\t\\t\\t{%if item.product.woo_type == \\\"variable\\\" %}\\n                          {% if item.product.woo_price_from == item.product.woo_price_to %}\\n\\t\\t\\t\\t\\t\\t\\t\\t<span class=\\\"product-text-price uc_sale_price\\\">{{item.product.woo_price|wc_price|raw}}<\\/span> \\n                          {% else %}\\n\\t\\t\\t\\t\\t\\t\\t\\t<span class=\\\"product-text-price uc_sale_price\\\">{{item.product.woo_price_from|wc_price(item.product.woo_price_from_id)|raw}}<\\/span> - <span class=\\\"product-text-price uc_sale_price\\\">{{item.product.woo_price_to|wc_price(item.product.woo_price_to_id)|raw}}<\\/span>\\n\\t\\t\\t\\t\\t\\t  {% endif %}\\n\\t\\t\\t\\t\\t{%else%}\\n\\t\\t\\t\\t\\t\\t<span class=\\\"product-text-price uc_sale_price\\\">{{item.product.woo_price|wc_price(item.product.id)|raw}}<\\/span> \\n\\t\\t\\t\\t    {%endif%}\\n\\t\\t\\t\\t{% endif %}\\n                \\n              <\\/div> \\n              \\n               \\n                <div class=\\\"product-text-wrapper uc-buttons\\\"> \\n                  \\n                  {% if (show_product_button == \\\"true\\\") and (product_button_type == \\\"content\\\") %} \\n                      \\n                      \\t<a {{item.product.dynamic_popup_link_attributes|raw}} class=\\\"product-text-btn {{item.product.dynamic_popup_link_class}}\\\" > {{product_page_button_text|raw}}<\\/a> <span class=\\\"uc_btn_spacer\\\" style=\\\"display:inline-block;\\\"><\\/span> \\n                  \\n                  {% endif %}\\n                  \\n                  {% if cart_button == \\\"content\\\" %} \\n                  \\n                      {% if(item.product.woo_type == \\\"variable\\\") %}\\n                          {% set buttonAddCartTextCombined = select_options_button_text %}        \\t\\n                      {% else %}\\n                          {% set buttonAddCartTextCombined = cart_button_text %}\\n                      {% endif %}\\n                                    \\n                          <a {{item.product.woo_addcart_ajax_attributes|raw}}>{{ buttonAddCartTextCombined|raw}}<\\/a>                  \\n                                    \\t\\n                  {% endif %}\\n                \\n              <\\/div>\\n                \\n{% if(enable_third_party_integrations == \\\"true\\\")%}\\n\\t{{do_action(\'ue_woocommerce_product_integrations_bottom\', item.product.id)}}\\n{%endif%}\\n              \\n\\t\\t\\t<\\/div>\\n<\\/li>\",\"css\":\"#{{uc_id}}  *{\\n\\tbox-sizing:border-box;\\n}\\n\\n#{{uc_id}} ul\\n{\\n  padding:0px;\\n  margin:0px;\\n  display:grid;\\n}\\n#{{uc_id}} .product-img{\\n\\t\\n    flex-grow:0;\\n    flex-shrink:0;\\n    display:flex;\\n    align-items:center;\\n    justify-content:center;\\n    position:relative;\\n    overflow:hidden;\\n}\\n\\n#{{uc_id}} .product-img img\\n{\\n  display:block;\\n}\\n\\n \\n#{{uc_id}} .product-items{\\n\\tdisplay: flex;\\n\\talign-items:{{content_align}};\\n}\\n\\n\\n#{{uc_id}} .product-items:last-child{\\n    margin-bottom:0px;\\n}\\n\\n#{{uc_id}} .product-text{\\nflex-grow:1;\\n}\\n\\n.product-text-name\\n{\\n  font-size: 21px;\\n}\\n\\n#{{uc_id}} .product-text-name{\\n\\tdisplay: block;\\n\\ttext-decoration: none;\\n\\t\\n}\\n\\n#{{uc_id}} .uc-buttons a {\\n\\tcursor: pointer;\\n\\ttext-decoration: none;\\n    text-align:center;\\n    transition:0.3s;\\n}\\n\\n.uc-button-addcart.added\\n{\\n  display:none !important;\\n}\\n\\n#{{uc_id}} .ue_woocommerce_product_list_badge\\n{\\n  display:inline-flex;\\n  align-items:center;\\n  justify-content:center;\\n}\\n\\n.ue_woocommerce_product_grid_out_of_stock_label, .ue_woocommerce_product_list_badge\\n{\\n  font-size:12px;\\n}\\n\\n#{{uc_id}} .ue_woocommerce_product_grid_out_of_stock_label{\\n display:inline-flex;\\n align-items:center;\\n justify-content:center;\\n}\\n\\n#{{uc_id}} .product-img-overlay\\n{\\n  position:absolute;\\n  top:0;\\n  bottom:0;\\n  right:0;\\n  left:0;\\n  flex-direction:column;\\n  display:flex;\\n  align-items:center;\\n  transition:0.3s;\\n}\\n\\n#{{uc_id}} .product-img-overlay .uc-buttons\\n{\\n  text-align:center;\\n  width:100%;\\n}\\n\\n{% if badge == \\\"image\\\" %}\\n    #{{uc_id}} .ue_woocommerce_product_list_badge\\n\\t{\\n      position:absolute;\\n      {{vertical_snap}}:{{label_vertical_distance}}px;\\n      {{horizontal_snap}}:{{label_horizontal_distance}}px;\\n    }\\n\\t#{{uc_id}} .ue_woocommerce_product_grid_out_of_stock_label{\\n      position: absolute;\\n      {{horizontal_snap}}:{{label_horizontal_distance}}px;\\n      {{vertical_snap}}:{{label_vertical_distance}}px;\\n      z-index: 1;\\n\\t}\\n{% endif %}\\n\\n\\n{% if collapse_on_mobile == \\\"true\\\" %}\\n\\n@media only screen and (max-width: {{collapse_from_resolution}}px) {\\n  #{{uc_id}} .product-items{\\n    flex-wrap: wrap;\\n   }\\n}\\n\\n\\n{% endif %}\\n\\n#{{uc_id}} .jet-wishlist-button__container{\\n  \\tmargin-top:10px;\\n}\",\"css_item\":\"{% if item.product.woo_sale_price is empty %}\\n\\t#{{item.item_id}} .uc_sale_currency\\n    {\\n      display:none\\n    }\\n{% else %} \\n\\t#{{item.item_id}} .uc_regular_price\\n    {\\n      text-decoration:line-through !important;\\n    }\\n{% endif %}\",\"js\":\"jQuery(document).ready(function(){\\n    \\n  var objGrid = jQuery(\\\"#{{uc_id}}\\\");\\n    \\n  var objRemoteOptions = {\\n    \\tclass_items:\\\"product-items\\\",\\n    \\tclass_active:\\\"ue-active-item\\\",\\n      \\tadd_set_active_code:false\\n  };\\n  \\n  {{ucfunc(\\\"put_remote_parent_js\\\",\\\"objGrid\\\",\\\"objRemoteOptions\\\")}}  \\n \\n});\"}', '{\"options\":{\"addon_icon\":\"fas fa-shopping-basket\",\"addon_icon_svg\":\"\",\"dynamic_addon\":\"false\",\"dynamic_post\":\"\",\"dynamic_post_enable_customfields\":\"false\",\"dynamic_post_enable_category\":\"false\",\"description\":\"Showcase your WooCommerce products in an attractive list layout with many customization options. You can choose how many products to show per page, what information to display about each product, and much more.\",\"link_resource\":\"https:\\/\\/unlimited-elements.com\\/docs\\/woocommerce-product-list\\/\",\"link_preview\":\"https:\\/\\/unlimited-elements.com\\/woocommerce-product-list-widget-for-elementor\\/\",\"show_small_icon\":\"true\",\"preview_size\":\"full\",\"preview_custom_width\":\"\",\"preview_bgcol\":\"#ffffff\",\"special\":\"\",\"special_data\":\"\",\"items_section_title\":\"\",\"items_section_heading\":\"\",\"items_title_field\":\"\",\"path_assets\":\"woocommerce_product_list\",\"js_as_module\":false,\"preview_size_unite_selected_text\":\"Full Size\",\"is_free_addon\":true,\"is_new_addon\":false,\"is_last_updated\":false,\"is_trending\":false,\"enable_items\":false},\"params\":[{\"type\":\"uc_posts_list\",\"title\":\"Product\",\"name\":\"product\",\"description\":\"\",\"enable_condition\":false,\"condition_attribute\":\"\",\"condition_operator\":\"equal\",\"condition_value\":null,\"label_block\":false,\"use_custom_fields\":true,\"use_category\":true,\"default_max_posts\":\"\",\"for_woocommerce_products\":true,\"show_image_sizes\":true,\"enable_ajax\":true,\"font_editable\":false,\"__attr_catid__\":\"cat_general_general\"},{\"type\":\"uc_textfield\",\"title\":\"Product Page Button Text\",\"name\":\"product_page_button_text\",\"description\":\"\",\"enable_condition\":false,\"condition_attribute\":\"\",\"condition_operator\":\"equal\",\"condition_value\":null,\"default_value\":\"Details\",\"font_editable\":false,\"__attr_catid__\":\"cat_content_yv