INSERT INTO `wp_snippets` (`id`, `name`, `description`, `code`, `tags`, `scope`, `priority`, `active`, `modified`, `revision`, `cloud_id`) VALUES
(1, 'Make upload filenames lowercase', 'Makes sure that image and file uploads have lowercase filenames.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_filter( \'sanitize_file_name\', \'mb_strtolower\');', 'sample, media', 'global', 10, 0, '2024-04-11 19:26:27', 2, NULL),
(2, 'Disable admin bar', 'Turns off the WordPress admin bar for everyone except administrators.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_action( \'wp\', function () {\n	if ( ! current_user_can( \'manage_options\' ) ) {\n		show_admin_bar( false );\n	}\n} );\n', 'sample, admin-bar', 'front-end', 10, 0, '2024-04-11 19:27:22', 2, NULL),
(3, 'Allow smilies', 'Allows smiley conversion in obscure places.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_filter( \'widget_text\', \'convert_smilies\' );\nadd_filter( \'the_title\', \'convert_smilies\' );\nadd_filter( \'wp_title\', \'convert_smilies\' );\nadd_filter( \'get_bloginfo\', \'convert_smilies\' ); ', 'sample', 'global', 10, 0, '2024-04-11 19:28:07', 2, NULL),
(4, 'Current year', 'Shortcode for inserting the current year into a post or page..\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', '<?php echo date( \'Y\' ); ?>\n', 'sample, dates', 'content', 10, 0, '2024-04-11 19:28:02', 2, NULL),
(5, 'Specific Shipping methods', '', '/**\n * @snippet       Disable Payment Gateway For Specific Shipping Method\n * @how-to        Get CustomizeWoo.com FREE\n * @author        Rodolfo Melogli\n * @testedwith    WooCommerce 7\n * @donate $9     https://businessbloomer.com/bloomer-armada/\n */\n  \nadd_filter( \'woocommerce_available_payment_gateways\', \'bbloomer_gateway_disable_for_shipping_rate\' );\n  \nfunction bbloomer_gateway_disable_for_shipping_rate( $available_gateways ) {\n   if ( ! is_admin() && WC()->session ) {\n      $chosen_methods = WC()->session->get( \'chosen_shipping_methods\' );\n      $chosen_shipping = $chosen_methods[0];\n      if ( isset( $available_gateways[\'cod\'] ) && 0 === strpos( $chosen_shipping, \'local_pickup\' ) ) {\n         unset( $available_gateways[\'cod\'] );\n      }\n   }\n   return $available_gateways;\n} ', '', 'global', 10, 1, '2024-04-11 19:27:56', 2, NULL),
(6, 'new for selected shipping', '', 'add_filter( \'woocommerce_available_payment_gateways\', \'x34fg_gateway_disable_shipping\' );\n\nfunction x34fg_gateway_disable_shipping( $available_gateways ) {\n\n    global $woocommerce;\n\n    if ( !is_admin() ) {\n\n        $chosen_methods = WC()->session->get( \'chosen_shipping_methods\' );\n\n        $chosen_shipping = $chosen_methods[0];\n\n        if ( isset( $available_gateways[\'cod\'] ) && 0 === strpos( $chosen_shipping, \'local_pickup\' ) ) {\n            unset( $available_gateways[\'cod\'] );\n        }\n\n    }\n\nreturn $available_gateways;\n\n} ', '', 'global', 10, 1, '2024-04-11 19:27:51', 2, NULL),
(8, 'one option ', '', 'add_action(\'woocommerce_cart_calculate_fees\', \'custom_cash_on_delivery_fee\', 10, 1);\nfunction custom_cash_on_delivery_fee($cart) {\n    if (is_admin() && !defined(\'DOING_AJAX\')) return;\n\n    $chosen_payment_method = WC()->session->get(\'chosen_payment_method\');\n\n    if ($chosen_payment_method == \'cod\') {\n        $chosen_shipping_methods = WC()->session->get(\'chosen_shipping_methods\');\n\n        if (in_array(\'flat_rate:shipping_fee_greece\', $chosen_shipping_methods) || in_array(\'flat_rate:shipping_fee_other\', $chosen_shipping_methods)) {\n            $cart->add_fee(__(\'Shipping Fee\', \'woocommerce\'), 10); // Adjust the fee amount as needed\n        }\n    }\n}\n', '', 'global', 10, 1, '2024-04-11 19:27:44', 2, NULL),
(9, 'second option ', '', 'add_action(\'woocommerce_cart_calculate_fees\', \'remove_shipping_fee_for_direct_bank_transfer\', 10, 1);\nfunction remove_shipping_fee_for_direct_bank_transfer($cart) {\n    if (is_admin() && !defined(\'DOING_AJAX\')) return;\n\n    $chosen_payment_method = WC()->session->get(\'chosen_payment_method\');\n\n    if ($chosen_payment_method == \'Direct_bank_transfer\') {\n        $cart->remove_fee(\'greece\');\n        $cart->remove_fee(\'shipping_fee_other\');\n    }\n}\n', '', 'global', 10, 1, '2024-04-11 19:27:40', 2, NULL);
